// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(uint256 depositAmount, uint256 fuzzAddr) public {
        depositAmount = bound(depositAmount, 1, 1e36);
        address caller = address(uint160(uint256(keccak256(abi.encode(fuzzAddr)))));
        vm.assume(caller != address(0) && caller != address(this));

        vm.deal(caller, depositAmount);
        vm.prank(caller);
        (bool deposited,) = address(c).call{value: depositAmount}("");
        require(deposited, "deposit failed");

        vm.prank(caller);
        try c.withdraw() { } catch { }

        assertEq(c.balances(caller), 0);
    }
}
